draft.css:
@keyframes dk-pizza-duck { 0% { transform: translate(0px, 0px) rotate(0deg) } 25% { transform: translate(-8px, 0px) rotate(-8deg) } 50% { transform: translate(0px, -6px) rotate(0deg) } 75% { transform: translate(8px, 0px) rotate(8deg) } 100% { transform: translate(0px, 0px) rotate(0deg) } }
@keyframes dk-pizza-show { 0%, 100% { opacity: 1; transform: rotate(0deg) translateY(0px) } 40% { opacity: 1; transform: rotate(-28deg) translateY(-20px) } }
@keyframes dk-pizza-look { 0%, 100% { transform: rotate(0deg) } 40% { transform: rotate(-12deg) } }
@keyframes dk-pizza-chomp { 0% { transform: rotate(0deg) } 50% { transform: rotate(-14deg) } 100% { transform: rotate(0deg) } }
@keyframes dk-pizza-wing { 0% { transform: rotate(0deg) } 50% { transform: rotate(-38deg) } 100% { transform: rotate(0deg) } }
[data-part="duck"] { animation: dk-pizza-duck 1.8s ease-in-out 2 }
[data-part="hand-r"] { opacity: 1; animation: dk-pizza-show 1.8s ease-in-out 2 }
[data-part="head"] { animation: dk-pizza-look 1.8s ease-in-out 2 }
[data-part="beak"] { animation: dk-pizza-chomp 0.6s ease-in-out 6 }
[data-part="wing"] { animation: dk-pizza-wing 0.9s ease-in-out 4 }

